def compute(vars):
    value = vars["v1"]
    output_meta = {
        "currency": None,
        "scale": None,
        "unit": "ratio"
    }
    trace = {
        "input_values": {"v1": value},
        "output_meta": output_meta
    }
    return {
        "value": None if value is None else value,
        "trace": trace
    }
